import json
from src.nodes.base import BaseNode
from src.runtime.scene_validation import get_orphan_detector

class Hou_Mcp_Scene_Orphan_Check(BaseNode):
    name = "hou_mcp_scene_orphan_check"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_output("orphans_json")
        self.add_output("orphan_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw = (inputs.get("scene_layout_json") or "").strip()
        try:
            scene = json.loads(raw) if raw else {}
        except Exception:
            self.log_error("scene_layout_json is not valid JSON.")
            return {"orphans_json": "[]", "orphan_count": 0, "exec_out": True}
        try:
            orphans = get_orphan_detector().detect(scene)
            orphan_dicts = [o.to_dict() for o in orphans]
            if orphans:
                for o in orphans:
                    self.log_error(f"ORPHAN_OBJECT: {o.detail}")
            return {
                "orphans_json": json.dumps(orphan_dicts, sort_keys=True, indent=2),
                "orphan_count": len(orphans),
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Orphan detection failed: {exc}")
            return {"orphans_json": "[]", "orphan_count": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Scene_Orphan_Check
